                      <input
                        type="number"
                        min={0}
                        step="0.01"
                        value={price}
                        onChange={(e) => setPrice(e.target.value)}
                        className={cx(INPUT, 'ml-auto h-8 max-w-24 text-right')}
                        aria-label="Shop price"
                      />
                    ) : (
                      <span className="font-medium">{fmtInr(p.unit_price)}</span>
                    )}
                  </div>

                  <div className="text-right tabular-nums">
                    {isEditing ? (
                      <input
                        type="number"
                        min={0}
                        step="0.5"
                        value={stock}
                        onChange={(e) => setStock(e.target.value)}
                        className={cx(INPUT, 'ml-auto h-8 max-w-20 text-right')}
                        aria-label="Stock quantity"
                      />
                    ) : (
                      <span className={cx(lv === 'out' && 'text-destructive font-medium')}>
                        {p.stock_qty} {p.unit ?? ''}
                      </span>
                    )}
                  </div>

                  <div className="col-span-2 flex items-center justify-end gap-2 sm:col-span-1">
                    {!isEditing && (
                      <StatusPill tone={LEVEL_TONE[lv]} pulse={lv === 'out'}>
                        {LEVEL_LABEL[lv]}
                      </StatusPill>
                    )}
                    {isEditing ? (
                      <>
                        <Button
                          size="sm"
                          onClick={() => save(p)}
                          disabled={busy}
                          className="h-8 gap-1.5"
                        >
                          <Save className="size-3.5" /> Save
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => setEditing(null)}
                          disabled={busy}
                          className="h-8 px-2"
                          aria-label="Cancel"
                        >
                          <X className="size-4" />
                        </Button>
                      </>
                    ) : (
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => startEdit(p)}
                        className="text-muted-foreground hover:text-foreground h-8 px-2"
                        aria-label={`Edit ${p.name}`}
                      >
                        <Pencil className="size-3.5" />
                      </Button>
                    )}
                  </div>
                </li>
              );
            })}
          </ul>
        </div>
      )}

      {db && (
        <p className="text-muted-foreground mt-4 flex items-center gap-1.5 text-xs">
          <TriangleAlert className="size-3.5 text-amber-500" />
          Low-stock threshold is {LOW_STOCK} {`—`} items at or below show as “Low”.
        </p>
      )}
    </div>
  );
}

